mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM user_posts
    WHERE id = #{postId}
      AND deleted = 0
)

mapper.update:
UPDATE post_comments
SET content = #{content},
    updated_at = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE post_comments
SET deleted = 1,
    deleted_at = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND deleted = 0
